import React from 'react';
import DateFormatter from 'Common/Components/DateFormatter';
import formatNumber from 'Common/Functions/FormatNumber';
import {
  WrapperActivity, Time, BulletColumn, Bullet, EntryContent, ActivityDescription,
  Vulnerabilities, VulnerabilitiesQuantity, VulnerabilitiesText, HostsAndServices,
  Author, Dark, Light, Tool, ToolText
} from './styled';
import { AGENT, REPORT } from './constants';
import getAuthorAndFile from './utils';

const ActivityEntry = ({ activity, translations, isFirst, isLast, onSelect }) => {
  const isAgent = activity.import_source === AGENT;
  const isReport = activity.import_source === REPORT;
  const { author, fileName } = getAuthorAndFile(activity);

  const assets = activity.hosts_count ? `${formatNumber(activity.hosts_count)} ${translations.assets}` : translations.noAssets;
  const services = activity.services_count ? `${formatNumber(activity.services_count)} ${translations.services}` : translations.noServices;

  const onKeyDown = (event) => {
    if (event.key !== 'Enter' && event.key !== ' ') return;
    event.preventDefault();
    onSelect();
  };

  return (
    <WrapperActivity
      role="button"
      tabIndex={ 0 }
      onClick={ onSelect }
      onKeyDown={ onKeyDown }
    >
      <Time><DateFormatter date={ activity.date } hideYear /></Time>
      <BulletColumn $isFirst={ isFirst } $isLast={ isLast }>
        <Bullet />
      </BulletColumn>
      <EntryContent>
        <ActivityDescription>
          <Vulnerabilities>
            <VulnerabilitiesQuantity>{ formatNumber(activity.vulnerabilities_count) }</VulnerabilitiesQuantity>
            <VulnerabilitiesText>{ translations.vulnerabilities }</VulnerabilitiesText>
          </Vulnerabilities>
          <HostsAndServices>{ `${assets} ${services}` }</HostsAndServices>
        </ActivityDescription>
        { isAgent && (
          <Author>
            <Light>{ translations.triggeredBy } </Light>
            <Dark>{ author }</Dark>
          </Author>
        ) }
        { isReport && (
          <Author>
            <Dark>{ author }</Dark>
            <Light> { translations.imported } </Light>
            <Dark>{ fileName }</Dark>
          </Author>
        ) }
        { activity.tool && <Tool><ToolText>{ activity.tool }</ToolText></Tool> }
      </EntryContent>
    </WrapperActivity>
  );
};

export default ActivityEntry;
