import { AGENT, REPORT } from './constants';

/**
 * Resolves who originated an activity and the file it came from.
 * Agent runs are attributed to the command that triggered them; report imports
 * to the user who uploaded the file, with the queue prefix stripped from its name.
 *
 * @param {Object} activity - Activity feed entry, as returned by the API.
 * @returns {{ author: string, fileName: string }} - Author and file name to display.
 */
const getAuthorAndFile = (activity) => {
  if (activity.import_source === AGENT) return { author: activity.command, fileName: activity.params };
  if (activity.import_source === REPORT) {
    const params = activity.params || '';
    const prefixIndex = params.indexOf('_');
    return { author: activity.creator, fileName: params.slice(prefixIndex + 1) };
  }
  return { author: activity.creator, fileName: activity.params };
};

export default getAuthorAndFile;
